import React, { useEffect, useRef, useState } from "react";
import mapboxgl from "mapbox-gl";
import "mapbox-gl/dist/mapbox-gl.css";

import { useGlacierLayer } from "./glaciers";
import Loc from "./loc";
import "./glaciermap.css";
import PitchControl from "./PitchControl";
import SearchBar from "./search";
import Hotkey from "./Hotkey";
import MapLegend from "./MapLegend";
import BetaPopup from "./popup";

// cd /Users/seanfagan/Desktop/OGI

mapboxgl.accessToken =
 process.env.REACT_APP_MAPBOX_TOKEN;

const GlacierMap = () => {
  const mapContainer = useRef(null);
  const mapRef = useRef(null);

  const DEFAULT_PITCH = 50;
  const DEFAULT_BEARING = 0;
  const [pitch, setPitch] = useState(DEFAULT_PITCH);
  const [bearing, setBearing] = useState(DEFAULT_BEARING);
  const [selectedMountain, setSelectedMountain] = useState("hood");
  const [loading, setLoading] = useState(true);
  const [, setLogMessages] = useState([]);
  const [progress, setProgress] = useState(0);
  const [cursorInfo, setCursorInfo] = useState({
    lat: null,
    lng: null,
    elevM: null,
  });

  const updateProgress = (msg, step, totalSteps) => {
    console.log(msg);
    setLogMessages((prev) => [...prev, msg]);
    setProgress(Math.round((step / totalSteps) * 100));
  };

  const resetZoom = () => {
    const map = mapRef.current;
    if (!map) return;
    map.flyTo({
      center: [-121.69604, 45.36500],
      zoom: 14,
      speed: 2.2,
      pitch: DEFAULT_PITCH,
      bearing: DEFAULT_BEARING,
    });
    setPitch(DEFAULT_PITCH);
    setBearing(DEFAULT_BEARING);
  };


  useEffect(() => {
    const handleKeydown = (e) => {
      if (e.key.toLowerCase() === "r") resetZoom();
    };
    window.addEventListener("keydown", handleKeydown);
    return () => window.removeEventListener("keydown", handleKeydown);
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;

    const sync = () => setPitch(map.getPitch());
    map.on("pitch", sync);
    map.on("pitchend", sync);

    return () => {
      map.off("pitch", sync);
      map.off("pitchend", sync);
    };
  }, []);

  useEffect(() => {
    const initMap = async () => {
      if (mapRef.current) return;

      const totalSteps = 4;
      let step = 1;

      updateProgress("Initializing Mapbox map...", step++, totalSteps);

      mapRef.current = new mapboxgl.Map({
        container: mapContainer.current,
        style: "mapbox://styles/mapbox/satellite-streets-v12",
        center: [-121.69604, 45.36500],
        zoom: 14,
        pitch: DEFAULT_PITCH,
      });

      await new Promise((resolve) => mapRef.current.on("load", resolve));
      updateProgress("Mapbox map fully loaded", step++, totalSteps);

 
      if (!mapRef.current.getSource("mapbox-dem")) {
        mapRef.current.addSource("mapbox-dem", {
          type: "raster-dem",
          url: "mapbox://mapbox.mapbox-terrain-dem-v1",
          tileSize: 512,
          maxzoom: 14,
        });
        mapRef.current.setTerrain({ source: "mapbox-dem", exaggeration: 1.0 });
      }

      mapRef.current.on("mousemove", (e) => {
        const { lng, lat } = e.lngLat;
        const elevation = mapRef.current.queryTerrainElevation(e.lngLat, {
          exaggerated: false,
        });
        setCursorInfo({
          lat,
          lng,
          elevM: elevation !== null ? elevation.toFixed(1) : "N/A",
        });
      });

      mapRef.current.on("mouseleave", () => {
        setCursorInfo({ lat: null, lng: null, elevM: null });
      });

      const lakeMarkers = document.querySelectorAll(".marker, .place-marker");
      lakeMarkers.forEach((el) => (el.style.display = "none"));

      setLoading(false);
    };

    initMap();

    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, []);

  useGlacierLayer({ mapRef });

  return (
    <div style={{ position: "relative" }}>
      <div
        ref={mapContainer}
        style={{
          width: "100%",
          height: "calc(100vh - 43px)",
          overflow: "hidden",
          zIndex: 1,
        }}
      />

      <PitchControl
  mapRef={mapRef}
  value={pitch}
  onChange={setPitch}
  bearing={bearing}
  onBearingChange={setBearing}
/>;
      <Loc cursorInfo={cursorInfo} className="loc-readout" />
      <Hotkey resetZoom={resetZoom} />
      <BetaPopup loading={loading} progress={progress} title="Loading Data..." />
      <MapLegend
  selectedId={selectedMountain}
  onSelect={(m) => {
    setSelectedMountain(m.id);
    const map = mapRef.current;
    if (!map) return;
    map.flyTo({ center: m.center, zoom: m.zoom ?? 12.5, pitch: DEFAULT_PITCH, bearing: DEFAULT_BEARING, speed: 1.8 });
    setPitch(DEFAULT_PITCH);
    setBearing(DEFAULT_BEARING);
  }}
/>

    </div>
  );
};

export default GlacierMap;
